<?php declare(strict_types=1);namespace NpmGateway\Console;use NpmGateway\Services\MarketingFlyerNotificationHealthService;
final class MarketingFlyerNotificationHealthCommand{public function __construct(private readonly MarketingFlyerNotificationHealthService$health){}public function run(array$args):array{if($args!==[])return['exit_code'=>2,'stdout'=>'','stderr'=>"This command does not accept arguments.\n"];$r=$this->health->check();$lines=['Marketing Flyer Notification Worker','Heartbeat: '.($r['stale']?'STALE':'Healthy'),'Last successful run: '.$r['last_success'],'Pending deliveries: '.$r['pending'],'Retrying deliveries: '.$r['retry'],'Failed deliveries: '.$r['failed'],'Oldest pending age: '.$r['oldest_age']];if(!$r['heartbeat_found'])$lines[]='Worker heartbeat not found.';if($r['stale']){$lines[]='Production requires the Marketing Flyer notification worker to run every minute.';$lines[]='See docs/deployment/marketing-flyer-worker.md';}return['exit_code'=>$r['healthy']?0:1,'stdout'=>implode("\n",$lines)."\n",'stderr'=>''];}}
